    Rejects: negative numbers, exponents, more than two fractional digits.
    Returns Decimal if valid, raises ValueError otherwise.
    """
    value = value.strip()

    # Reject empty
    if not value:
        raise ValueError("Empty amount")

    # Reject exponents
    if 'e' in value.lower():
        raise ValueError("Exponent not allowed")

    # Check format: optional minus, digits, optional decimal with up to 2 digits
    if not re.match(r'^-?\d+(\.\d{1,2})?$', value):
        raise ValueError("Invalid amount format")

    try:
        amount = Decimal(value)
    except InvalidOperation:
        raise ValueError("Invalid decimal")

    # Reject negative
    if amount < 0:
        raise ValueError("Negative amount")

    return amount


def parse_csv_line(line: str) -> tuple:
    """Parse a CSV line into (category, amount).

    Returns tuple of (str, Decimal) or raises ValueError for malformed rows.
    """
    # Split into exactly two columns
    parts = line.split(',')
    if len(parts) != 2:
        raise ValueError(f"Expected 2 columns, got {len(parts)}")

    category = parts[0].strip()
    amount_str = parts[1].strip()

    # Category must be nonempty
    if not category:
        raise ValueError("Empty category")

    # Parse amount
    amount = parse_amount(amount_str)

    return (category, amount)


