    """Tests for parse_amount function."""

    def test_valid_whole_number(self):
        self.assertEqual(parse_amount("100"), Decimal("100"))
        self.assertEqual(parse_amount("0"), Decimal("0"))

    def test_valid_decimal_one_digit(self):
        self.assertEqual(parse_amount("10.5"), Decimal("10.5"))

    def test_valid_decimal_two_digits(self):
        self.assertEqual(parse_amount("10.50"), Decimal("10.50"))
        self.assertEqual(parse_amount("0.99"), Decimal("0.99"))

    def test_rejects_negative(self):
        with self.assertRaises(ValueError):
            parse_amount("-10.50")

    def test_rejects_exponent(self):
        with self.assertRaises(ValueError):
            parse_amount("1e5")

    def test_rejects_too_many_fractional_digits(self):
        with self.assertRaises(ValueError):
            parse_amount("10.123")

    def test_rejects_empty(self):
        with self.assertRaises(ValueError):
            parse_amount("")

    def test_rejects_whitespace_only(self):
        with self.assertRaises(ValueError):
            parse_amount("   ")

    def test_handles_whitespace(self):
        self.assertEqual(parse_amount("  10.50  "), Decimal("10.50"))


