    """Tests for validate_header function."""

    def test_valid_header(self):
        self.assertTrue(validate_header("category,amount"))

    def test_valid_header_with_whitespace(self):
        self.assertTrue(validate_header(" category,amount "))

    def test_invalid_header_missing_amount(self):
        self.assertFalse(validate_header("category,"))

    def test_invalid_header_wrong_order(self):
        self.assertFalse(validate_header("amount,category"))

    def test_invalid_header_extra_column(self):
        self.assertFalse(validate_header("category,amount,extra"))


