    """Tests for parse_csv_line function."""

    def test_valid_row(self):
        category, amount = parse_csv_line("food,10.50")
        self.assertEqual(category, "food")
        self.assertEqual(amount, Decimal("10.50"))

    def test_valid_row_with_whitespace(self):
        category, amount = parse_csv_line(" food , 10.50 ")
        self.assertEqual(category, "food")
        self.assertEqual(amount, Decimal("10.50"))

