        content = "category,amount\nfood,1e5"
        with self.assertRaises(ValueError):
            process_csv(content)

    def test_too_many_fractional_digits_raises(self):
        content = "category,amount\nfood,10.123"
        with self.assertRaises(ValueError):
            process_csv(content)


